function bindFilters(){var ids=['bbs-search','bbs-period','bbs-programme-filter','bbs-status-filter','bbs-category-filter'];ids.forEach(function(id){var el=document.getElementById(id);if(!el)return;el.onchange=el.oninput=function(){if(id==='bbs-search')BBS.search=this.value;else if(id==='bbs-period')BBS.filters.period=this.value;else if(id==='bbs-programme-filter')BBS.filters.programme=this.value;else if(id==='bbs-status-filter')BBS.filters.status=this.value;else BBS.filters.category=this.value;clearTimeout(BBS.filterTimer);BBS.filterTimer=setTimeout(render,180);};});}
