window.bbsReview=async function(id,decision){var reason=decision==='accepted'?'Quality criteria met':prompt('Reason/comment for '+statusLabel(decision));if(decision!=='accepted'&&!reason)return;var d=detailFor(id);if(d.observer_person_id&&String(d.observer_person_id)===String(personId())&&!['sephs_admin'].includes(activeRoleName()))return toastMsg('Self-review is prohibited. Assign another authorised validator.',false);try{var review={company_id:companyId(),observation_id:String(id),observation_version:d.record_version||1,validator_id:personId(),validator_name:personName(),decision:decision,reason:reason,comment:reason,quality_components:{context:20,specificity:25,feedback:20,barriers:20,routing:15},quality_score:decision==='accepted'?100:null,reviewed_at:new Date().toISOString(),created_by:personId()};await persist('bbs_quality_reviews',review);if(d.id)await patch('bbs_observation_details',d.id,{workflow_status:decision,reviewed_at:new Date().toISOString()});await audit('observation',id,'review_'+decision,d,review,reason);bbsCloseDrawer(true);BBS.loaded=false;await loadData(true);toastMsg('Quality decision recorded');}catch(e){toastMsg('Decision not saved: '+(e.message||'Please retry'),false);}};

