window.bbsOpenEntity=function(key,id){var row=(BBS.data[key]||[]).find(function(x){return String(x.id)===String(id);});if(!row)return;var hidden=['company_id','observer_person_id','before_json','after_json'],content=Object.keys(row).filter(function(k){return !hidden.includes(k)&&row[k]!==null&&row[k]!=='';}).map(function(k){var v=typeof row[k]==='object'?JSON.stringify(row[k]):row[k];return '<div class="bbs-list-row"><div><b>'+h(statusLabel(k))+'</b></div><span style="max-width:62%;text-align:right;overflow-wrap:anywhere">'+h(v)+'</span></div>';}).join('');var foot='<button class="bbs-btn" data-auris-module-onclick="e0041">Close</button>';if(canManage()&&['programmes','items','reports'].includes(key)&&row.status==='draft')foot='<button class="bbs-btn" data-auris-module-onclick="e0051" data-auris-module-args="'+encodeURIComponent(JSON.stringify([key,id]))+'">Submit review</button><button class="bbs-btn primary" data-auris-module-onclick="e0052" data-auris-module-args="'+encodeURIComponent(JSON.stringify([key,id]))+'">Publish</button>';drawer(statusLabel(key)+' record','<div class="bbs-card">'+content+'</div><div class="bbs-note" style="margin-top:12px">Referenced or published master data is retired or superseded, never hard-deleted.</div>',foot);};
window.bbsEntityTransition=async function(key,id,status){var row=(BBS.data[key]||[]).find(function(x){return String(x.id)===String(id);}),tableName=TABLES[key];if(!row||!tableName)return;if(status==='published'&&key==='programmes'&&(!row.checklist_version||!row.privacy_notice))return toastMsg('A checklist version and privacy notice are required before publication',false);try{var saved=await patch(tableName,id,{status:status,published_at:status==='published'?new Date().toISOString():null,published_by:status==='published'?personId():null});Object.assign(row,saved);await audit(key,id,'transition_'+status,null,saved);bbsCloseDrawer(true);render();toastMsg('Lifecycle state updated');}catch(e){toastMsg('Transition failed: '+(e.message||'Please retry'),false);}};
window.bbsCreateAction=function(themeId){var theme=(BBS.data.themes||[]).find(function(x){return String(x.id)===String(themeId);});if(!theme)return;var existing=(BBS.data.actionLinks||[]).find(function(x){return String(x.theme_id)===String(themeId);});if(existing)return bbsOpenAction(existing.action_id);var due=new Date();due.setDate(due.getDate()+(theme.criticality==='critical'?14:30));var title='Address BBS barrier: '+(theme.title||theme.signature||'confirmed theme'),description=[theme.context,theme.barrier_name?'Barrier: '+theme.barrier_name:null,'Evidence reviewed: '+(theme.evidence_count||0)+' observation(s)'].filter(Boolean).join('\n');drawer('Create governed corrective action','<div class="bbs-note"><strong>Single controlled workflow.</strong> Saving creates the authoritative Master Action, records the BBS relationship and marks this theme as actioned. If the relationship cannot be saved, the new action is automatically cancelled.</div><div class="bbs-form-grid" style="margin-top:12px">'+field('Action title','bbs-a-title','text',null,title,'full')+field('Description / required response','bbs-a-description','textarea',null,description,'full')+field('Priority','bbs-a-priority','select',[['low','Low'],['medium','Medium'],['high','High'],['critical','Critical']],theme.criticality==='critical'?'critical':'high')+field('Target completion date','bbs-a-due','date',null,due.toISOString().slice(0,10))+field('Action owner','bbs-a-owner','select',bbsActionPeopleOptions(theme.owner_id,theme.owner_name),theme.owner_id||'')+field('Owner name (when no People record exists)','bbs-a-owner-name','text',null,theme.owner_name||'')+'</div>','<button class="bbs-btn" data-auris-module-onclick="e0041">Cancel</button><button id="bbs-a-save" class="bbs-btn primary" data-auris-module-onclick="e0053" data-auris-module-args="'+encodeURIComponent(JSON.stringify([themeId]))+'"><i class="ti ti-link-plus"></i> Create and link action</button>');BBS.drawerDirty=true;};
