window.bbsValidateConfig=function(){var issues=[];if(value('bbs-c-ranking')==='purpose_controlled')issues.push('Named negative analytics requires Privacy Administrator approval and purpose logging.');if(value('bbs-c-group')&&Number(value('bbs-c-group'))<5)issues.push('Minimum group below 5 increases re-identification risk.');drawer('Configuration impact test','<div class="bbs-card"><div class="bbs-card-title">Impact preview</div><div class="bbs-list"><div class="bbs-list-row"><b>Active programmes affected</b><strong>'+(BBS.data.programmes||[]).filter(function(x){return x.status==='active'||x.status==='published';}).length+'</strong></div><div class="bbs-list-row"><b>Historical observations rewritten</b><strong>0</strong></div><div class="bbs-list-row"><b>New forms affected</b><strong>Future records only</strong></div><div class="bbs-list-row"><b>Validation warnings</b><strong>'+issues.length+'</strong></div></div></div>'+(issues.length?'<div class="bbs-note warn" style="margin-top:12px">'+issues.map(h).join('<br>')+'</div>':'<div class="bbs-note" style="margin-top:12px">No blocking conflict identified by the client-side preview. Server validation remains authoritative.</div>'),'<button class="bbs-btn primary" data-auris-module-onclick="e0041">Close preview</button>');};
